'use strict';
/**
 * FE mock server data contributor for the entity set TestCase (draft root of ZUI_STC_TEST_CASE_O4).
 *
 * Thin adapter only: the behavior (determinations, validations, feature control, actions) lives in
 * mock-backend/services/TestCaseService.js — the stand-in for the RAP behavior implementation.
 * Initial data: TestCase.json (generated by tools/seed/generate-seed.js).
 */
const service = require('../../../../mock-backend/services/TestCaseService');
const { DRAFT_ACTIONS, addMessages, run, applyDerived, refreshResponse } = require('../../../../mock-backend/services/mockServerAdapter');

const ACTIONS = {
    analyze: (repo, keys) => service.analyze(repo, keys),
    validate: (repo, keys) => service.validateTestCase(repo, keys, { asStateMessages: true }),
    revalidate: (repo, keys) => service.validateTestCase(repo, keys, { asStateMessages: false }),
    approve: (repo, keys) => service.approve(repo, keys),
    startExecution: (repo, keys) => service.startExecution(repo, keys),
    refreshExecution: (repo, keys) => service.refreshExecution(repo, keys),
    cancelExecution: (repo, keys) => service.cancelExecution(repo, keys)
};

/** requests that changed the process profile of a draft (onBefore → onAfterUpdateEntry) */
const profileChanges = new WeakSet();

module.exports = {
    /** new draft (Create): initial values */
    async onBeforeAddEntry(keys, data) {
        Object.assign(data, service.initialTestCase(data), service.deriveTestCase({ ...data, ...service.initialTestCase(data) }));
    },

    /** new draft (Create): 1:1 child TestCaseData with the defaults of the process profile */
    async onAfterAddEntry(keys, data, odataRequest) {
        await run(this, odataRequest, async (repo) => {
            await service.createTestData(repo, data);
            await service.syncDerived(repo, data.TestCaseUUID);
        });
    },

    async onBeforeUpdateEntry(keys, updatedData, odataRequest) {
        const stored = (await this.base.fetchEntries(keys, odataRequest))[0];
        if (stored && stored.ProcessProfile !== updatedData.ProcessProfile) {
            profileChanges.add(odataRequest);
        }
    },

    async onAfterUpdateEntry(keys, updatedData, odataRequest) {
        await run(this, odataRequest, async (repo) => {
            if (profileChanges.has(odataRequest)) {
                profileChanges.delete(odataRequest);
                await service.onProcessProfileChanged(repo, updatedData);
            }
            await service.syncDerived(repo, updatedData.TestCaseUUID);
        });
    },

    /** RAP virtual elements / instance feature control: always derived from the current state */
    async onAfterRead(data, odataRequest) {
        return applyDerived(data, async (row) => {
            if (!row.TestCaseUUID || row.IsActiveEntity === undefined) {
                return undefined;
            }
            const stored = (await this.base.fetchEntries({ TestCaseUUID: row.TestCaseUUID, IsActiveEntity: row.IsActiveEntity }, odataRequest))[0];
            return stored ? service.deriveTestCase(stored) : undefined;
        });
    },

    /** bound actions analyze · validate · approve · startExecution · refreshExecution · cancelExecution · revalidate */
    async executeAction(actionDefinition, actionData, keys, odataRequest) {
        const action = ACTIONS[actionDefinition.name];
        if (!action) {
            return actionData;
        }
        return run(
            this,
            odataRequest,
            async (repo) => {
                const tcKeys = { TestCaseUUID: keys.TestCaseUUID, IsActiveEntity: keys.IsActiveEntity === true || keys.IsActiveEntity === 'true' };
                const { messages } = await action(repo, tcKeys);
                await service.syncDerived(repo, tcKeys.TestCaseUUID);
                addMessages(odataRequest, messages);
                return repo.findOne('TestCase', tcKeys);
            },
            { boundAction: true }
        );
    },

    /** Prepare (Save, step 1): determination on save — validate silently */
    async onDraftPrepare(actionDefinition, responseData, keys, odataRequest) {
        await run(this, odataRequest, async (repo) => {
            const messages = await service.prepare(repo, { TestCaseUUID: keys.TestCaseUUID, IsActiveEntity: false });
            await service.syncDerived(repo, keys.TestCaseUUID);
            addMessages(odataRequest, messages);
            refreshResponse(responseData, await repo.findOne('TestCase', { TestCaseUUID: keys.TestCaseUUID, IsActiveEntity: false }));
        });
    },

    /** Edit / Activate / Discard change the draft flags: re-derive feature control; Activate assigns the Case ID */
    async onAfterAction(actionDefinition, actionData, keys, responseData, odataRequest) {
        const response = await responseData;
        if (!DRAFT_ACTIONS.has(actionDefinition.name) || !keys?.TestCaseUUID) {
            return response;
        }
        return run(this, odataRequest, async (repo) => {
            if (actionDefinition.name === 'Activate') {
                await service.onActivated(repo, keys);
            }
            await service.syncDerived(repo, keys.TestCaseUUID);
            if (response?.TestCaseUUID) {
                refreshResponse(response, await repo.findOne('TestCase', { TestCaseUUID: response.TestCaseUUID, IsActiveEntity: response.IsActiveEntity }));
            }
            return response;
        });
    }
};
